<?php use App\Core\Security; ?><h4>عملیات گروهی محصولات</h4><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="card card-body mb-3"><div class="row g-2 align-items-end"><div class="col-md-3"><select name="action" class="form-select"><option value="activate">فعال‌سازی</option><option value="deactivate">غیرفعال‌سازی</option><option value="importance">تغییر اهمیت</option></select></div><div class="col-md-3"><select name="importance" class="form-select"><option value="1">عادی</option><option value="2">مهم</option><option value="3">بحرانی</option></select></div><div class="col-md-3"><button class="btn btn-primary">اجرای عملیات انتخاب‌شده</button></div></div></div><table class="table table-bordered"><thead><tr><th><input type="checkbox" id="all"></th><th>کد</th><th>نام</th><th>اهمیت</th><th>وضعیت</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><input class="item" type="checkbox" name="ids[]" value="<?=$r['id']?>"></td><td><?=Security::e($r['product_code'])?></td><td><?=Security::e($r['product_name'])?></td><td><?=$r['importance']?></td><td><?=$r['is_active']?'فعال':'غیرفعال'?></td></tr><?php endforeach;?></tbody></table></form><script>document.getElementById('all')?.addEventListener('change',e=>document.querySelectorAll('.item').forEach(x=>x.checked=e.target.checked));</script>